            top: -2,
            child: DecoratedBox(
              key: const ValueKey('gscale-device-attention'),
              decoration: BoxDecoration(
                color: scheme.error,
                shape: BoxShape.circle,
                border: Border.fromBorderSide(
                  BorderSide(color: scheme.surface, width: 2),
                ),
              ),
              child: const SizedBox(width: 10, height: 10),
            ),
          ),
      ],
    );
  }
}

Future<void> selectOfflinePrintDevice(BuildContext context) async {
  try {
    final profile = await PrintService.detectOfflinePrinter();
    if (context.mounted) {
      Navigator.of(context).pop(PrintDeviceSelection.offline(profile));
    }
  } catch (error) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('USB printer aniqlanmadi: $error')),
      );
    }
  }
}

